// Source/DOM-event/layout-rule checks. They do not execute a browser CSS engine or claim Figma completion.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {helpers,entityKey} from '../lib/idol/design-review/cw-runtime/shared/helpers.js';
import {harness} from './helpers/cw-review-dom.mjs';
import {production} from './helpers/cw-main-loader.mjs';
import edges from '../lib/idol/design-review/cw-runtime/member-video-relations.json' with {type:'json'};
import {verifiedParticipations,validateParticipation,videosForMember,membersForVideo} from '../lib/idol/design-review/cw-runtime/member-video-relations.mjs';
import {parseRoute,returnDestination} from '../lib/idol/design-review/cw-runtime/shared/router.js';
const tick=()=>new Promise(resolve=>setImmediate(resolve));const root=new URL('../lib/idol/design-review/cw-runtime/',import.meta.url);
const groups={};for(const slug of ['cherrybullet','weeekly'])groups[slug]=await import(new URL('groups/'+slug+'/index.js',root));
const expected={cherrybullet:8,weeekly:7};
for(const slug of Object.keys(groups)){
 const {artist,render}=groups[slug];
 test(slug+': every declared public appearance matches exact original video tuple and has no fabricated rating/native proof',()=>{
  const selected=edges.filter(e=>e.slug===slug);assert.equal(selected.length,expected[slug]);assert.equal(verifiedParticipations(artist).length,selected.length);
  for(const edge of selected){assert(validateParticipation(edge,artist));assert.equal(edge.ratingId,null);assert.equal(edge.nativeRelationProven,false);for(const change of [{groupId:'foreign'},{videoId:'same-song-other-edit'},{version:'英文版'},{slotType:'STAGE'},{videoType:'另一视频类型'},{memberId:'not-a-source-member'}])assert(!validateParticipation({...edge,...change},artist));}
  for(const stage of artist.works.filter(w=>w.type==='stage'))assert.equal(membersForVideo(artist,stage).length,0,'MV evidence must never propagate to same-title or same-parent stage');
  if(slug==='cherrybullet')for(const name of ['KOKORO','LINLIN'])assert.equal(videosForMember(artist,artist.members.find(m=>m.name===name)).length,0);
 });
 test(slug+': named source/photo locator and official exact-video evidence remain independently readable at their recorded SHA',()=>{
  assert(process.env.CW_EVIDENCE_ROOT,'Set CW_EVIDENCE_ROOT to the package evidence directory');
  for(const edge of edges.filter(e=>e.slug===slug)){
   for(const kind of ['identity','version']){const proof=edge.evidence[kind],file=path.join(process.env.CW_EVIDENCE_ROOT,proof.file.replace(/^evidence\//,'')),bytes=fs.readFileSync(file);assert.equal(createHash('sha256').update(bytes).digest('hex'),proof.sha256);const text=bytes.toString('utf8');assert(text.includes(kind==='identity'?proof.literalName:edge.videoId));if(kind==='identity')assert(proof.adjacentImage||Number.isInteger(proof.adjacentImageRef));}
  }
 });
 test(slug+': real adapter click chain member → exact MV → same member restores the full member/filter origin',async()=>{
  const edge=edges.find(e=>e.slug===slug),h=harness(slug,'#/'+slug+'/members?q='+encodeURIComponent(artist.members.find(m=>m.id===edge.memberId).nameZh));
  const mod=await import(new URL(slug+'-host.mjs',root)),name=slug==='cherrybullet'?'Cherrybullet':'Weeekly',api=mod['create'+name+'Review']({host:h.host,window:h.win,production});h.loadStyles();await api.ready;
  const member=api.root.querySelector('[data-portrait-member="'+edge.memberId+'"]');assert(member);h.click(member);await tick();
  const memberUrl=h.win.location.hash;const toWork=api.root.querySelector('[data-member-video="'+edge.videoId+'"]');assert(toWork);h.click(toWork);await tick();assert.equal(parseRoute(h.win.location.hash).key,edge.workId);
  const backToMember=api.root.querySelector('[data-video-member="'+edge.memberId+'"]');assert(backToMember);h.click(backToMember);await tick();assert.equal(h.win.location.hash,memberUrl);assert.equal(parseRoute(returnDestination(parseRoute(h.win.location.hash))).query.get('q'),artist.members.find(m=>m.id===edge.memberId).nameZh);
  const native=api.root.querySelector('[data-'+slug+'-native]');assert(native.disabled,'Public appearance does not prove a private record relation');assert.equal(h.assigned.length,0);api.destroy();assert.equal(h.frames.size,0);assert.equal(h.timers.size,0);
 });
 test(slug+': home includes the entire applicable roster as real source photos with full Chinese names, never a collapsed carousel',()=>{
