  if(slug==='cherrybullet'){assert(html.includes('2023 · 七人时期'));assert(html.includes('十位历史成员'));assert(css.includes('repeat(5,minmax(0,1fr))'));assert(css.includes('aspect-ratio:5/7'));}
  else{assert(html.includes('2021 · OSEN'));assert(html.includes('wk-roster-history'));assert(css.includes('aspect-ratio:auto!important'));assert(!/object-fit:cover/.test(css));}
 });
