for(const slug of Object.keys(groups))test(slug+': every linked image keeps recovery controls in its static tile, outside the anchor, and retry preserves navigation and image identity',async()=>{
 const {artist}=groups[slug],name=slug==='cherrybullet'?'Cherrybullet':'Weeekly';
 const {mediaManifest,createLocalImageResolver}=await import(new URL(slug+'-images.mjs',root));
 const entries=mediaManifest.images.map(r=>({groupId:artist.id,slug,canonicalPath:r.path,sha256:r.sha256,bytes:r.bytes,naturalWidth:r.naturalWidth,naturalHeight:r.naturalHeight,qualityLevel:r.declaredQualityLevel,url:'/_sol15-originals/'+slug+'/'+r.sha256+'/'+r.path.split('/').at(-1)}));
 const edge=edges.find(e=>e.slug===slug),h=harness(slug);
 const host=await import(new URL(slug+'-host.mjs',root));
 const api=host['create'+name+'Review']({host:h.host,window:h.win,production,resolveImage:createLocalImageResolver(entries,h.win.location.origin)});h.loadStyles();await api.ready;
 let checked=0;
 for(const hash of ['#/'+slug,'#/'+slug+'/members','#/'+slug+'/works','#/'+slug+'/member/'+edge.memberId,'#/'+slug+'/work/'+edge.workId]){
  assert(api.navigate(hash));await tick();
  for(const link of api.root.querySelectorAll('a[href]').filter(a=>a.querySelector('img'))){
   const image=link.querySelector('img'),tile=link.closest('[data-media-tile]');assert(tile);assert.notEqual(tile,link);assert.equal(link.parentNode,tile);
   const src=image.getAttribute('src'),href=link.getAttribute('href'),location=h.win.location.hash;image.dispatchEvent(new Event('error'));
   const control=tile.querySelector('[data-'+slug+'-image-retry]');assert(control);assert.equal(control.closest('a[href]'),null);assert.equal(control.parentNode.parentNode,tile);assert(image.hidden);
   h.click(control);assert.equal(h.win.location.hash,location);assert.equal(link.getAttribute('href'),href);assert.equal(image.getAttribute('src'),src);image.dispatchEvent(new Event('load'));assert.equal(tile.querySelector('[data-'+slug+'-image-retry]'),null);assert.equal(image.hidden,false);checked++;
  }
 }
 assert(checked>artist.members.length,'covers home, directory, work cards and reciprocal participation cards');api.destroy();assert.equal(h.frames.size,0);assert.equal(h.timers.size,0);
});
